import React from "react";

export default function Footer() {
  return (
    <footer className="site-footer">
      <div className="footer-top container">
        <div className="col">
          <h4>Useful Links</h4>
          <ul>
            <li>Login</li>
            <li>Application form</li>
            <li>Academic Calendar</li>
            <li>Results</li>
            <li>Photo Gallery</li>
          </ul>
        </div>

        <div className="col">
          <h4>Contact Us:</h4>
          <p>Address: A-7, Sector-24, Noida, Uttar Pradesh - 201301</p>
          <p>
            Landmarks: Opposite Sector 24 Police Station, near NTPC Noida, and
            near ESIC Hospital
          </p>
          <p>Phone: (0120) 4327434, (0120) 4327435</p>
          <p>
            Email: <a href="mailto:kvnoida03@gmail.com">kvnoida03@gmail.com</a>
          </p>
        </div>

        <div className="col">
          <h4>Location Map:</h4>
          <iframe
            title="map"
            src="https://www.google.com/maps?q=meerut&output=embed"
            style={{ width: "100%", height: 150, border: 0 }}
            loading="lazy"
          />
        </div>
      </div>

      <div className="footer-bottom">
        <div>
          Copyright 2015 Gandhi International Public School. All rights reserved.
        </div>

        <div className="social-icons">
          <a
            href="https://wa.me/919876543210"
            target="_blank"
            rel="noopener noreferrer"
            title="Chat on WhatsApp"
          >
            <i className="fa-brands fa-whatsapp"></i>
          </a>
          <a
            href="https://www.youtube.com/"
            target="_blank"
            rel="noopener noreferrer"
            title="Visit YouTube"
          >
            <i className="fa-brands fa-youtube"></i>
          </a>
          <a
            href="https://twitter.com/"
            target="_blank"
            rel="noopener noreferrer"
            title="Follow us on Twitter"
          >
            <i className="fa-brands fa-twitter"></i>
          </a>
        </div>
      </div>
    </footer>
  );
}
